# owner: platform
"""Weekly timesheet rows built from a list of shifts."""

from typing import Dict, Iterable, List
from collections import Counter

from hourglass.schedule import worker_minutes
from hourglass.models import Shift

def _check_shifts(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts given")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("blank worker name")

def _line(name: str, count: int, minutes: int) -> str:
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} hours"

def _busiest_first(minutes: Dict[str, int]) -> List[str]:
    def order(name: str):
        return (-minutes[name], name)
    return sorted(minutes, key=order)

def _render(counts: Counter, minutes: Dict[str, int]):
    lines = []
    for name in _busiest_first(minutes):
        total = minutes[name]
        lines.append(_line(name, counts[name], total))
    return lines

# ---
def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, most hours first."""
    rows = list(shifts)
    _check_shifts(rows)
    counts = Counter(item.worker for item in rows)
    minutes = worker_minutes(rows)
    return _render(counts, minutes)

