# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span

BUSY = [
    Shift("Brisa", "mon", Span(480, 600)),
    Shift("Anil", "mon", Span(480, 720)),
    Shift("Anil", "tue", Span(480, 600)),
]
EXPECTED = [
    "Anil: 2 shifts, 6.0 hours",
    "Brisa: 1 shifts, 2.0 hours",
]

def make_shift(worker, start, end):
    return Shift(worker, "mon", Span(start, end))

class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        self.assertEqual(timesheet_lines(BUSY), EXPECTED)

    def test_one_decimal_place(self):
        lines = timesheet_lines([make_shift("Bo", 0, 100)])
        self.assertEqual(lines, ["Bo: 1 shifts, 1.7 hours"])

    def test_ties_sorted_by_name(self):
        lines = timesheet_lines([
            make_shift("Zed", 0, 60),
            make_shift("Amy", 0, 60),
        ])
        self.assertTrue(lines[0].startswith("Amy"))

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_lines([make_shift("  ", 0, 60)])
